merge graph.AssetEdge T using ( select SG.$node_id as from_id, OG.$node_id as to_id, I.ID, I.[Uid], I.IntersectTypeID, T.[Uid] as IntersectTypeUid, T.PredicateID, P.[Uid] as PredicateUid, P.[Type] as PredicateType, '<props/>' as Properties, I.[State], coalesce(I.UpdatedOn, I.CreatedOn, getutcdate()) as UpdatedOn from [Intersect] I inner join Asset SA on SA.[Object] = I.[Subject] and SA.ObjectID = I.SubjectID inner join graph.AssetNode SG on SG.ID = SA.ID inner join Asset OA on OA.[Object] = I.[Object] and OA.ObjectID = I.ObjectID inner join graph.AssetNode OG on OG.ID = OA.ID inner join IntersectType T on T.ID = I.IntersectTypeID inner join [Predicate] P on P.ID = T.PredicateID ) S on (S.ID = T.ID and S.from_id = T.$from_id and S.to_id = T.$to_id) when matched and (T.UpdatedOn < S.UpdatedOn) then update set T.IntersectTypeID = S.IntersectTypeID, T.IntersectTypeUid = S.IntersectTypeUid, T.PredicateID = S.PredicateID, T.PredicateUid = S.PredicateUid, T.PredicateType = S.PredicateType, T.[State] = S.[State] when not matched by target then insert ($from_id, $to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, PredicateUid, PredicateType, Properties, [State], UpdatedOn) values (from_id, to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, PredicateUid, PredicateType, Properties, [State], UpdatedOn);
if @populatePaths = 1 begin
drop table if exists #assetTypes; create table #assetTypes (ID int, [Level] int);
with h as ( select A.Object, A.ObjectID, A.ID, null as ParentID, 1 as [Level] from AssetType A left join IntersectTypeDetail I on I.Object = A.Object and I.ObjectID = A.ObjectID and I.PredicateType in (3,4) where I.ID is null union all select A.Object, A.ObjectID, A.ID, P.ID as ParentID, P.[Level]+1 as [Level] from AssetType A inner join IntersectTypeDetail I on I.Object = A.Object and I.ObjectID = A.ObjectID and I.PredicateType in (3,4) inner join h as P on P.Object = I.Subject and P.ObjectID = I.SubjectID )
insert into #assetTypes select ID, [Level] from h order by [Level];
while ((select count(*) from #assetTypes) > 0) begin declare @id int; select top 1 @id = ID from #assetTypes order by [Level];
print @id
exec graph.PopulatePathsForAssetType @id;
delete from #assetTypes where id = @id; end end else begin drop table if exists #assets; create table #assets (AssetTypeID int, ID bigint); insert into #assets select AssetTypeID, ID from graph.AssetNode where Class not in (3,5,10,11,12,13) and ( [Path] is null or Segments is null );
while ((select count(*) from #assets) > 0) begin declare @assetTypeId int, @assetId bigint; select top 1 @assetTypeId = AssetTypeID, @assetId = ID from #assets;
exec graph.PopulatePathsForAssetType @assetTypeId, @assetId;
delete from #assets where ID = @assetId; end
-- Catch-all update graph.AssetNode set Segments = '<path><segment level="1" assetTypeId="' + cast(AssetTypeID as varchar) + '" assetId="' + cast(ID as varchar) + '">{INVALID}</segment></path>' where Class not in (3,5,10,11,12,13) and Segments is null and [Path] is not null; end
